export function getUnitIdByName(unitName: string): string {
  const norm = (unitName || '').trim().toLowerCase();
  if (norm.includes('كيلو') || norm.includes('كجم') || norm.includes('kg')) return 'u-kg';
  if (norm.includes('جرام') || norm.includes('جم') || norm.includes('g')) return 'u-g';
  if (norm.includes('صاج')) return 'u-saj';
  if (norm.includes('عبوة')) return 'u-box';
  if (norm.includes('جار')) return 'u-jar';
  if (norm.includes('بيضة')) return 'u-egg';
  if (norm.includes('ظرف')) return 'u-zarf';
  if (norm.includes('علبة')) return 'u-can';
  if (norm.includes('طبق')) return 'u-portion';
  return 'u-pcs';
}

export function getWarehouseIdByDept(dept: string): string {
  const norm = (dept || '').trim();
  if (norm.includes('أسبونش')) return 'wh-sponge-dept';
  if (norm.includes('الألبان')) return 'wh-dairy-dept';
  if (norm.includes('معلبات')) return 'wh-assembly-dept';
  return 'wh-raw-store';
}

